Algorithm RowSums
  Dimension m[3, 3] As Integer;
  For f <- 0 To 2 Do
    For c <- 0 To 2 Do
      Read m[f, c];
    EndFor
  EndFor
  For f <- 0 To 2 Do
    Define sum As Integer <- 0;
    For c <- 0 To 2 Do
      sum <- sum + m[f, c];
    EndFor
    Write sum;
  EndFor
EndAlgorithm
